def chain_follow(chain):
    chain_dict = {}
    for token in chain:
        if token not in chain_dict:
            chain_dict[token] = []
        chain_dict[token].append(token)

    current = chain_dict[chain[0]]
    result = []

    while current:
        next_token = current.pop()
        result.append(next_token)

        if next_token not in chain_dict:
            continue

        next_token_list = chain_dict[next_token]
        next_token_index = next_token_list.index(next_token)

        if next_token_index == len(next_token_list) - 1:
            break

        next_token_list.pop(next_token_index + 1)

        current = next_token_list

    return ','.join(result)
